// src/utils/api.ts
async function createStreamReq(content2) {
  const API_CF_ENDPOINT = requireEnv("API_CF_ENDPOINT");
  const STREAM_API_KEY = requireEnv("STREAM_API_KEY");
  const response = await fetch(`${API_CF_ENDPOINT}/streaming`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "x-api-key": STREAM_API_KEY
    },
    body: JSON.stringify({ content: content2, type: "note", author: "bbki.ng" })
  });
  if (!response.ok) {
    const error = await response.text();
    throw new Error(`Failed to create stream: ${error}`);
  }
  return response.json();
}
async function createPost(title, content2) {
  const API_CF_ENDPOINT = requireEnv("API_CF_ENDPOINT");
  const STREAM_API_KEY = requireEnv("STREAM_API_KEY");
  const response = await fetch(`${API_CF_ENDPOINT}/posts`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "x-api-key": STREAM_API_KEY
    },
    body: JSON.stringify({ title, content: content2 })
  });
  if (!response.ok) {
    const error = await response.text();
    throw new Error(`Failed to create post: ${error}`);
  }
  const result = await response.json();
  return result.data;
}

// package.json
var package_default = {
  name: "bbbot",
  version: "1.2.0",
  description: "Campfire bot with COC Master AI integration",
  main: "src/worker.ts",
  scripts: {
    dev: "wrangler dev src/worker.ts",
    deploy: "wrangler deploy",
    release: "node build/build.mjs"
  },
  keywords: [],
  author: "",
  license: "ISC",
  dependencies: {
    "@ai-sdk/anthropic": "^1.1.0",
    ai: "^4.1.0",
    zod: "^3.23.0"
  },
  devDependencies: {
    esbuild: "0.24.0",
    typescript: "^5.5.2",
    wrangler: "^3.84.0"
  }
};

// src/campfire/handlers.ts
function isAdmin(userId) {
  const ids = (getEnv("ADMIN_IDS") ?? "").split(",").map(Number);
  return ids.includes(userId);
}
function escapeHtml(text2) {
  return text2.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
var help = async () => {
  return [
    "<strong>Available commands:</strong>",
    "",
    "<strong>help</strong> - Show this help message",
    "<strong>avatar</strong> - Get bbki.ng logo",
    "<strong>version</strong> - Show bot version",
    "",
    "<strong>Creating content (admin only):</strong>",
    "Single-line message = Stream (appears in real-time feed)",
    "Multi-line message = Blog post (first line = title, rest = body)"
  ].join("<br>\n");
};
var avatar = async () => {
  return `<img src="https://bbki.ng/pwa-512x512.png" alt="bbki.ng logo" width="256" height="256">`;
};
var version = async () => {
  return `bbbot v${package_default.version} running on Campfire.`;
};
var content = async (payload) => {
  const text2 = payload.message.body.plain;
  const lines = text2.split("\n");
  if (!isAdmin(payload.user.id)) {
    return `You are not authorized to create content.`;
  }
  if (lines.length < 2) {
    return handleStream(lines[0].trim());
  }
  return handlePost(lines[0].trim(), lines.slice(1).join("\n").trim());
};
async function handleStream(content2) {
  if (!content2) return "Cannot create empty stream.";
  const result = await createStreamReq(content2);
  return `Stream created: <strong>${escapeHtml(result.data.id)}</strong>`;
}
async function handlePost(title, body) {
  if (!title) return "Post title cannot be empty.";
  const post = await createPost(title, body);
  return `Post created: <a href="https://bbki.ng/blog/${escapeHtml(post.id)}">${escapeHtml(title)}</a>`;
}

